    # enclose cells, with the diagonals converging on a lower mark.
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0:
                continue
            # A top/base boundary row has two equal-color marks, and a
            # descending diagonal sequence connects them inward to the apex.
            for d in range(1, min(h-r, w-c)):
                left,right=c-d,c+d
                if left<0 or right>=w:
                    continue
                if grid[r+d][left]==grid[r+d][right]==grid[r][c]:
                    for rr in range(r, r+d+1):
                        span=rr-r
                        for cc in range(c-span+1,c+span):
                            if grid[rr][cc]==0:
                                out[rr][cc]=2
    # Specifically detect a downward-pointing triangle with its two upper
    # corners joined by diagonal marks to a lower apex.
    for r in range(h):
        for c1 in range(w):
            if grid[r][c1]==0: continue
            for c2 in range(c1+2,w):
                if grid[r][c2]!=grid[r][c1]: continue
                d=(c2-c1)//2
                if c2-c1 != 2*d or r+d>=h: continue
                if all(grid[r+k][c1+k]==grid[r+k][c2-k]==grid[r][c1] for k in range(d+1)):
                    for rr in range(r,r+d):
                        for cc in range(c1+1+(rr-r),c2-(rr-r)):
                            if grid[rr][cc]==0: out[rr][cc]=2
