                if grid[ar+d][left] == color and grid[ar+d][right] == color:
                    for rr in range(ar+1, ar+d+1):
                        span = rr-ar
                        for cc in range(ac-span+1, ac+span):
                            if grid[rr][cc] == 0:
                                out[rr][cc] = 2
    # Also fill a wedge whose top edge is a pair of marked endpoints and
    # whose sides converge diagonally to a lower point.
    for r in range(h):
